import {RHCA,dimensionMatrix,trajectoryMarkup,validAnchor,hasDimensionIssue} from './pipeline-viz.js';
import {assessBatch} from './pipeline-contract.js';
import {saveFile} from './studio.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={coding:'Coding Agent',healthcare:'Healthcare Assistant',fintech:'FinTech Agent'};
const patterns={steady_high:'Stable high anchors',late_drop:'Late severe drop',early_low:'Same mean, early low anchor',recovery_retained:'Correction retains the earlier drop',single_anchor:'One dimension reaches Anchor 1',mild_decline:'BTV below threshold without Anchor 1',steady_threshold:'Stable anchors at threshold',missing_dimension:'One dimension not reported',normal:'Within constraints',late_failure:'Late failure',persistent_failure:'Persistent failure',repaired:'Corrected after failure',success_with_violation:'Success with a violation'};
const fmt=n=>Number.isFinite(n)?n.toFixed(2):'—';
const csvCell=s=>'"'+String(s??'').replaceAll('"','""')+'"';

export function createPipeline(api){
 let batch=null,inputs=null,domain='all',routing='all',criterion='all',selected=null,checkpoint=null,cellDimension='A',rhcaDimension='all',loadPromise=null,busy=false,batchId='filter';
 const batchCache=new Map();
 const openedRuns=new WeakMap();
 const root=()=>document.querySelector('#main');
 const domainOf=r=>r.original?.domain||'unknown', keyOf=r=>String(batch.records.indexOf(r));
 const visible=()=>batch.records.filter(r=>(domain==='all'||domainOf(r)===domain)&&(routing==='all'||r.route===routing)&&(criterion==='all'||r.run?.issues.some(i=>i.criterion_id===criterion))&&(rhcaDimension==='all'||hasDimensionIssue(r,rhcaDimension)));
 async function chooseBatch(id){
  if(!batchCache.has(id))batchCache.set(id,await Promise.all(['results','input'].map(async name=>{const r=await fetch('data/'+(id==='filter'?'filter':'pipeline')+'/'+name+'.json');if(!r.ok)throw Error('Batch data unavailable.');return r.json()})));
  [batch,inputs]=batchCache.get(id);batchId=id;selected=String(Math.max(0,batch.records.findIndex(r=>['late_drop','success_with_violation'].includes(r.original?.pattern))));domain=routing=criterion=rhcaDimension='all';checkpoint=null;
 }
 async function load(){if(!loadPromise)loadPromise=chooseBatch('filter').catch(e=>{loadPromise=null;throw e});return loadPromise;}
 function summary(){const r=batch.records;return {n:r.length,events:r.reduce((n,x)=>n+(x.original?.events?.length||0),0),valid:r.filter(x=>x.run).length,btv:r.filter(x=>x.btv?.status==='computed').length,...Object.fromEntries(['candidate','problem','review'].map(k=>[k,r.filter(x=>x.route===k).length]))};}
 function heatmap(){const domains=[...new Set(batch.records.map(r=>domainOf(r)))],cols=[['current-goal','Goal'],['authorization','Permission'],['action-result','Tool result'],['interface','State'],['artifact-check','Verification'],['verified-completion','Completion']];
  return '<div class="pipe-table-scroll"><table class="pipe-heatmap"><caption>Trajectories with failing event checks. Select a cell to filter.</caption><thead><tr><th scope="col">Domain</th>'+cols.map(([,n])=>'<th scope="col">'+n+'</th>').join('')+'</tr></thead><tbody>'+domains.map(d=>{const rows=batch.records.filter(r=>domainOf(r)===d);return '<tr><th scope="row">'+esc(names[d]||d)+'</th>'+cols.map(([id,n])=>{const count=rows.filter(r=>r.run?.issues.some(i=>i.criterion_id===id)).length;return '<td><button class="pipe-cell '+(count?'affected':'')+' '+(domain===d&&criterion===id?'selected':'')+'" data-pipe-cell="'+esc(id)+'" data-domain="'+esc(d)+'" aria-label="'+esc(names[d]||d)+', '+n+': '+count+' of '+rows.length+' trajectories"><strong>'+count+'</strong><small>/ '+rows.length+'</small></button></td>'}).join('')+'</tr>'}).join('')+'</tbody></table></div>';
 }
 function chart(item){return trajectoryMarkup(item,checkpoint,cellDimension);}
 function detail(){const list=visible();let item=list.find(r=>keyOf(r)===selected)||list[0];if(!item)return '<div class="results-empty">No records match. <button class="text-link" data-pipe="reset">Clear filters</button></div>';selected=keyOf(item);
  const b=item.btv,run=item.run,first=run?.issues.slice().sort((a,b)=>a.first_observed-b.first_observed)[0],event=first&&run.events.find(e=>e.id===first.first_event_id),dim=first?.dimension||run?.dimension||'goal';
  const ratings=Array.isArray(item.original?.rhca)?item.original.rhca:[],focus=Number.isInteger(checkpoint)&&checkpoint<ratings.length?checkpoint:Math.max(0,ratings.findIndex(r=>RHCA.some(d=>r?.scores?.[d.id]===1))),rated=ratings[focus],focusedEvent=run?.events.find(e=>e.id===rated?.event_id)||event;
  return '<section class="pipe-case" aria-label="Selected trajectory"><div class="pipe-case-top"><div><span class="eyebrow">'+esc(names[item.original?.domain]||item.original?.domain||'Imported')+'</span><h2>'+esc(patterns[item.original?.pattern]||item.id)+'</h2></div><label class="pipe-select"><span class="sr-only">Select trajectory</span><select id="pipe-case">'+list.map(r=>'<option value="'+keyOf(r)+'" '+(keyOf(r)===selected?'selected':'')+'>'+esc(r.id)+' · '+esc(patterns[r.original?.pattern]||r.route)+'</option>').join('')+'</select></label></div><div class="pipe-case-grid"><div>'+chart(item)+'<div class="pipe-score-row"><div><span>Arithmetic mean</span><strong>'+fmt(b?.arithmetic_mean)+'</strong></div><div><span>BTV · '+(b?.status==='computed'?(b.passed?'pass':'below threshold'):'unavailable')+'</span><strong>'+fmt(b?.score)+'</strong></div><div><span>Recorded final check</span><strong>'+(run?(item.task_success?'Pass':'Fail'):'Unknown')+'</strong></div></div></div><aside class="pipe-evidence"><span class="pipe-route '+item.route+'">'+esc(item.route==='candidate'?'Candidate set':item.route==='problem'?'Problem cases':'Needs review')+'</span><p>'+esc(item.reasons.join(' '))+'</p>'+(focusedEvent?'<span class="eyebrow">CHECKPOINT '+(focus+1)+' · EVENT '+esc(focusedEvent.id)+'</span><blockquote>'+esc(focusedEvent.text)+'</blockquote>':'')+'<div class="rhca-evidence-anchors">'+RHCA.map(d=>'<span class="'+(cellDimension===d.id?'rhca-active-anchor':'')+'" style="--dimension-color:'+d.color+'"><i>'+d.id+'</i><strong>'+(validAnchor(rated?.scores?.[d.id])?rated.scores[d.id]:'—')+'</strong></span>').join('')+'</div>'+(b?.critical_anchor_turns?.length?'<p class="small-note">Anchor 1 retained at rated checkpoints '+b.critical_anchor_turns.join(', ')+'.</p>':'')+(run?'<div class="pipe-case-links"><button class="text-link" data-pipe="workbench">'+(item.original?.provenance?.extension==='controlled-rhca-v1'?'View baseline events →':'Inspect evidence →')+'</button>'+(item.original?.provenance?.extension==='controlled-rhca-v1'?'':'<button class="text-link" data-pipe="garden">Explore garden →</button>')+'</div>':'')+'</aside></div><details class="pipe-details"><summary>Data & method</summary><dl><div><dt>Case</dt><dd>'+esc(item.id)+'</dd></div><div><dt>Data / ratings</dt><dd>'+esc(item.original?.provenance?.data_type||'Importer-supplied provenance')+' · '+esc(item.original?.provenance?.rating_source||'Rating provenance not recorded')+'</dd></div><div><dt>Model family / version</dt><dd>'+esc(item.original?.provenance?.model_family||'N/A')+' / '+esc(item.original?.provenance?.model_id||'N/A')+'</dd></div><div><dt>Paper task</dt><dd>'+esc(item.original?.provenance?.paper_task||'Not recorded')+' · author-designed extension, not original study observations</dd></div><div><dt>BTV</dt><dd>§3.2 Eq. (1) · p = 1 · λ = 0.5 · threshold = 2 · equal RHCA weights. Missing dimensions are not imputed. Anchor 1 is reported separately.</dd></div><div><dt>Policy</dt><dd>batch-routing-v1 · invalid / incomplete → review; event failures, BTV below threshold or Anchor 1 → problem; otherwise → candidate. Originals retained.</dd></div></dl><p class="small-note">Controlled rating tests use passing baseline event records and independently supplied score sequences; they test the verifier and policy, not semantic scoring. Healthcare rules compare recorded IDs and approvals; they do not assess clinical correctness. Synthetic labels do not establish semantic evaluator accuracy.</p><button class="text-link" data-pipe="one">Download this result · JSON ↓</button></details></section>';
 }
 function filterOutputs(s){return '<section class="filter-outputs" aria-label="Filter output sets"><div>'+[['candidate','Candidate set'],['problem','Problem cases'],['review','Needs review']].map(([id,label])=>'<button data-filter-route="'+id+'" aria-pressed="'+(routing===id)+'"><span>'+label+'</span><strong>'+s[id]+'</strong></button>').join('')+'</div><button class="text-link" data-pipe="filtered">Filtered inputs · JSON ↓</button></section>';}
 function draw(){if(location.hash.split('?')[0]!=='#pipeline')return;const s=summary();root().innerHTML='<section class="workspace-heading"><div><span class="eyebrow">SYNTHETIC TRAJECTORY FILTERING</span><h1>Pipeline &amp; Insights</h1><p>Filter supplied trajectories with BTV.</p></div><div class="heading-actions"><label class="pipe-batch-select"><span class="sr-only">Select evaluation batch</span><select id="pipe-batch" '+(busy?'disabled':'')+'><option value="filter" '+(batchId==='filter'?'selected':'')+'>Controlled rating tests · 24</option><option value="pipeline" '+(batchId==='pipeline'?'selected':'')+'>Original event fixtures · 60</option>'+(batchId==='imported'?'<option value="imported" selected>Imported batch</option>':'')+'</select></label><label class="quiet-button pipe-upload">Import batch<input id="pipe-upload" type="file" accept="application/json,.json" '+(busy?'disabled':'')+'></label><button class="button primary" data-pipe="run" '+(busy?'disabled':'')+'>'+(busy?'Evaluating…':'Run filter →')+'</button></div></section><div class="pipe-provenance"><span class="pipe-label">'+(batch.summary.generator==='synthetic-agent-protocol-v1'?'SYNTHETIC DEMONSTRATION':'LOCAL BATCH')+'</span><span>'+esc(batch.summary.generator==='synthetic-agent-protocol-v1'?(batchId==='filter'?'Controlled RHCA anchors over a passing event baseline · no model calls.':'Scripted logs and RHCA anchors · no model calls.'):batch.summary.scope)+'</span></div><ol class="pipe-flow" aria-label="Batch processing stages">'+[['Import',s.n+' retained'],['Validate',s.valid+' executable'],['Evaluate',s.btv+' BTV results'],['Route',s.candidate+' candidate · '+s.problem+' problem · '+s.review+' review'],['Export','JSON + CSV']].map(([a,b],i)=>'<li><span>0'+(i+1)+'</span><strong>'+a+'</strong><small>'+esc(b)+'</small></li>').join('')+'</ol>'+filterOutputs(s)+'<div class="pipe-section-heading"><h2>Behavior across dimensions</h2><div class="pipe-filters"><label><span class="sr-only">Filter domain</span><select id="pipe-domain"><option value="all">All domains</option>'+[...new Set(batch.records.map(r=>domainOf(r)))].map(d=>'<option value="'+esc(d)+'" '+(d===domain?'selected':'')+'>'+esc(names[d]||d)+'</option>').join('')+'</select></label><label><span class="sr-only">Filter route</span><select id="pipe-routing">'+[['all','All routes'],['candidate','Candidate set'],['problem','Problem cases'],['review','Needs review']].map(([v,n])=>'<option value="'+v+'" '+(routing===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+((domain!=='all'||routing!=='all'||criterion!=='all'||rhcaDimension!=='all')?'<button class="text-link" data-pipe="reset">Reset</button>':'')+'</div></div>'+dimensionMatrix(batch.records,{domain,dimension:rhcaDimension,names,synthetic:batch.summary.generator==='synthetic-agent-protocol-v1'})+'<details class="pipe-rule-disclosure"><summary>Event rule checks</summary>'+heatmap()+'</details><div id="pipe-detail">'+detail()+'</div><footer class="pipe-export"><span>'+s.n+' logs · '+s.events.toLocaleString()+' events · '+fmt(batch.summary.evaluation_seconds)+' s · '+esc(batch.summary.runtime||'Python local batch')+'<small>Measured for this batch on this machine; not a scalability benchmark.</small></span><div><button class="text-link" data-pipe="json">Results · JSON ↓</button><button class="text-link" data-pipe="csv">Summary · CSV ↓</button>'+(!batch.summary.runtime?'<a class="text-link" href="data/'+(batchId==='filter'?'filter':'pipeline')+'/synthetic-pipeline-results.zip" download>Complete bundle ↓</a>':'')+'</div></footer>';
  root().querySelector('.pipe-section-heading').before(root().querySelector('#pipe-detail'));
 }
 async function render(){await load();draw();}
 document.addEventListener('change',async e=>{
  if(e.target.id==='pipe-batch'){const id=e.target.value;if(id==='imported')return;busy=true;draw();try{await chooseBatch(id)}catch(err){api.toast(err.message)}finally{busy=false;draw()}return;}
  if(e.target.id==='pipe-domain'){domain=e.target.value;criterion=rhcaDimension='all';checkpoint=null;draw()}
  if(e.target.id==='pipe-routing'){routing=e.target.value;draw()}
  if(e.target.id==='pipe-case'){selected=e.target.value;checkpoint=null;document.querySelector('#pipe-detail').innerHTML=detail()}
  if(e.target.id==='pipe-upload'){try{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('Choose an input JSON array smaller than 5 MB.');const value=JSON.parse(await file.text());await execute(value,true)}catch(err){api.toast(err.message)}}
 });
 async function execute(value,isImport=false){if(busy)return;busy=true;draw();try{await new Promise(resolve=>setTimeout(resolve,30));const start=performance.now(),records=assessBatch(value),elapsed=(performance.now()-start)/1000;inputs=structuredClone(value);if(isImport)batchId='imported';batch={schema_version:1,records,summary:{records:records.length,evaluation_seconds:elapsed,runtime:'Browser local evaluation',evaluated_at:new Date().toISOString(),generator:value.every(r=>r?.provenance?.generator==='synthetic-agent-protocol-v1')?'synthetic-agent-protocol-v1':null,scope:'Ratings are supplied, not generated. Rules inspect recorded fields; originals and all routing reasons are retained.',policy_version:'batch-routing-v1'}};domain=routing=criterion=rhcaDimension='all';checkpoint=null;selected=String(Math.max(0,records.findIndex(r=>['late_drop','success_with_violation'].includes(r.original?.pattern))));api.toast(records.length+' records evaluated locally. No model called.')}finally{busy=false;draw()}}
 document.addEventListener('click',async e=>{const dp=e.target.closest('[data-rhca-dimension]'),cp=e.target.closest('[data-rhca-checkpoint]');if(dp){domain=dp.dataset.domain;rhcaDimension=dp.dataset.rhcaDimension;criterion=routing='all';checkpoint=null;draw();root().querySelector('#pipe-detail').scrollIntoView({block:'start'});return;}if(cp){checkpoint=Number(cp.dataset.rhcaCheckpoint);cellDimension=cp.dataset.rhcaCell||'A';document.querySelector('#pipe-detail').innerHTML=detail();return;}const cell=e.target.closest('[data-pipe-cell]');if(cell){domain=cell.dataset.domain;criterion=cell.dataset.pipeCell;rhcaDimension='all';checkpoint=null;draw();return}const set=e.target.closest('[data-filter-route]')?.dataset.filterRoute;if(set){routing=set;domain=criterion=rhcaDimension='all';checkpoint=null;draw();return;}const action=e.target.closest('[data-pipe]')?.dataset.pipe;if(!action||!batch)return;
  if(action==='reset'){domain=routing=criterion=rhcaDimension='all';checkpoint=null;draw()}
  if(action==='run')try{await execute(inputs)}catch(err){api.toast(err.message)}
  if(action==='filtered')saveFile('filtered-'+routing+'-inputs.json',JSON.stringify(visible().map(r=>r.original),null,2),'application/json');
  if(action==='json')saveFile('pipeline-results.json',JSON.stringify(batch,null,2),'application/json');
  if(action==='csv'){const rows=[['id','domain','route','final_check_passed','btv','arithmetic_mean','reasons'],...visible().map(r=>[r.id,r.original?.domain,r.route,r.task_success,r.btv?.score,r.btv?.arithmetic_mean,r.reasons.join(' ')])];saveFile('pipeline-summary.csv',rows.map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv')}
  const item=visible().find(r=>keyOf(r)===selected);
  if(action==='one'&&item)saveFile('pipeline-'+item.id.replace(/[^\w-]/g,'')+'.json',JSON.stringify(item,null,2),'application/json');
  if(['garden','workbench'].includes(action)&&item?.run){const r=structuredClone(item.run),ratings=Array.isArray(item.original?.rhca)?item.original.rhca:[],focus=Number.isInteger(checkpoint)?checkpoint:Math.max(0,ratings.findIndex(a=>RHCA.some(d=>a?.scores?.[d.id]===1))),event=r.events.find(e=>e.id===ratings[focus]?.event_id),issue=r.issues.find(i=>i.failing_events.includes(event?.id));const stored=openedRuns.get(item)||api.addRun(r);openedRuns.set(item,stored);location.hash=api.route(action==='garden'?'garden':'diagnostics',stored.id,event?.sequence||1,issue?.dimension||stored.dimension)}
 });
 return {render};
}
